import assert from 'node:assert/strict';
import {createGenerationHarness} from './bsh-product/test/helpers/generation-harness.mjs';
import {regionFixture} from './bsh-product/test/helpers/region-fixture.mjs';
import {createDetailGrid, detailCellPolygon, detailCellAreaSquareMiles} from './bsh-product/src/detailGrid.ts';

async function open(data) {
  const h=createGenerationHarness(42);
  h.render();
  h.guardRandom();
  h.setWindow({alert: message=>{throw Error(message);}, matchMedia:()=>({matches:false})});
  h.injectFunction('readTextFile',async f=>f.text);
  await h.render().handleImportJson({target:{files:[{text:JSON.stringify(data)}],value:''}});
  h.render();
  return h;
}

function save(h) {
  const data=JSON.parse(JSON.stringify(h.render().createSaveData()));
  delete data.savedAt;
  return data;
}

const input=regionFixture('classic',{river:true});
input.map.regions[0].pointsOfInterest.push({q:1,r:0});
input.map.regions[0].pointOfInterestKinds['1,0']='ruins';
input.map.roads=[];
input.map.crossings=[];
const h=await open(input);
h.render().setEditMode(true);
h.render().setSelectedHex({q:2,r:0});
h.render().setSelectedHexBiomeOverride('plain_deciduous_forest');
let edited=save(h);
assert.equal(edited.map.biomeOverrideByHexKey['2,0'],'plain_deciduous_forest');
assert.equal(edited.map.regions[0].pointOfInterestKinds['2,0'],'village');
const river=edited.map.rivers[0];
assert.ok(river);
assert.equal(h.render().editRoadDocument({type:'create',path:[{q:1,r:0},{q:2,r:0}],kind:'trail'}),true);
edited=save(h);
assert.equal(edited.map.roads.length,1);
assert.deepEqual(edited.map.roads[0].segments,[{from:{q:1,r:0},to:{q:2,r:0},kind:'trail'}]);
assert.deepEqual(edited.map.rivers[0],river);
const reopened=save(await open(edited));
assert.deepEqual(reopened.map.roads,edited.map.roads);
assert.deepEqual(reopened.map.rivers,edited.map.rivers);
assert.deepEqual(reopened.map.crossings,edited.map.crossings);
assert.deepEqual(reopened.map.regions,edited.map.regions);
assert.deepEqual(reopened.map.biomeOverrideByHexKey,edited.map.biomeOverrideByHexKey);
const native=createDetailGrid(12), vertices=detailCellPolygon(native,{q:0,r:0});
const nativeCorner=Math.hypot(vertices[0].x-vertices[3].x,vertices[0].y-vertices[3].y);
assert.ok(Math.abs(nativeCorner-8*Math.sqrt(3))<1e-9);
assert.equal(native.convention,'across_flats');
console.log(JSON.stringify({
 hex:'2,0', biome:reopened.map.biomeOverrideByHexKey['2,0'], poi:reopened.map.regions[0].pointOfInterestKinds['2,0'],
 road:reopened.map.roads[0], crossings:reopened.map.crossings, riverId:river.id, roundTrip:true,
 grid:{step:native.step,convention:native.convention,nativeCorner,nativeArea:detailCellAreaSquareMiles(native),sourceCorner:12,sourceFlats:6*Math.sqrt(3),sourceArea:54*Math.sqrt(3)}
}));
